#include "fp_primitives.h"
#include <fenv.h>
#include <stdio.h>
#include <stdlib.h>
#include <math.h>
#define DECL(name) void name(size_t,size_t,size_t,size_t,const float**,const float*,float*,size_t,size_t,size_t,const float*,const struct xnn_f32_minmax_params*)
DECL(test_neon);DECL(test_rvv);
static uint32_t state=0xc802471a;
static uint32_t next_bits(void){state^=state<<13;state^=state>>17;state^=state<<5;return state;}
static float from_bits(uint32_t b){float f;memcpy(&f,&b,4);return f;}
static uint32_t bits(float f){uint32_t b;memcpy(&b,&f,4);return b;}
static int same(float x,float y){return x==y||(isnan(x)&&isnan(y));}
static float sample(unsigned mode){static const uint32_t special[]={0,0x80000000,1,0x80000001,0x7fffff,0x800000,0x3f800000,0xbf800000,0x7f7fffff,0xff7fffff,0x7f800000,0xff800000,0x7fc00001,0xffc12345,0x7f800001};uint32_t b=next_bits();if(mode==0)return (float)((int)(b%17)-8)*0.25f;if(mode==1)b=special[b%(sizeof(special)/sizeof(*special))];return from_bits(b);}
static float oracle(size_t col,size_t K,size_t E,const float**table,const float*zero,size_t off,const float*W,float lo,float hi){size_t base=(col/8)*8*(1+E*K),lane=col%8;float x=W[base+lane];for(size_t e=0;e<E;e++){const float*a=table[e];if(a!=zero)a+=off;for(size_t k=0;k<K;k++)x=fmaf(a[k],W[base+8+8*(e*K+k)+lane],x);}if(isnan(x)||isnan(lo)||isnan(hi))return from_bits(0x7fc00000);return fmaxf(fminf(x,hi),lo);}
static int witness(void){float a[]={0.0f/0.0f},w[16]={0},l[1]={0},r[1]={0};const float*table[]={a};w[8]=1.0f;struct xnn_f32_minmax_params p={{-1,1}};test_neon(1,1,4,8,table,w,l,0,32,0,a,&p);test_rvv(1,1,4,8,table,w,r,0,32,0,a,&p);printf("counterexample mr=1 N=1 K=1 entries=1 a=%08x bias=00000000 weight=3f800000 lo=bf800000 hi=3f800000 neon=%08x rvv=%08x\n",bits(a[0]),bits(l[0]),bits(r[0]));return isnan(l[0])&&r[0]==1.0f?0:1;}
int main(int argc,char**argv){if(fesetround(FE_TONEAREST))return 2;if(argc>1)return witness();size_t cases=0,cells=0;for(size_t N=1;N<=25;N++)for(size_t K=1;K<=13;K++)for(size_t E=1;E<=5;E++)for(unsigned pattern=0;pattern<5;pattern++)for(unsigned mode=0;mode<3;mode++){size_t off=2,extent=K+off+4,nw=((N+7)/8)*8*(1+E*K);float*A=malloc(3*extent*4),*AS=malloc(3*extent*4),*W=malloc(nw*4),*WS=malloc(nw*4),*L=malloc((N+2)*4),*R=malloc((N+2)*4);const float**table=malloc(E*sizeof(*table));const float**copy=malloc(E*sizeof(*copy));if(!A||!AS||!W||!WS||!L||!R||!table||!copy)return 3;for(size_t j=0;j<3*extent;j++)A[j]=sample(mode);for(size_t j=0;j<nw;j++)W[j]=sample(mode);const float*zero=A+2*extent;for(size_t e=0;e<E;e++)table[e]=pattern==0?A+(e%2)*extent:pattern==1?A:pattern==2?zero:pattern==3?(e%2?zero:A):A+(e%2);memcpy(copy,table,E*sizeof(*table));memcpy(AS,A,3*extent*4);memcpy(WS,W,nw*4);for(size_t j=0;j<N+2;j++){L[j]=from_bits(0x4f123456);R[j]=from_bits(0xcf654321);}float lo=mode==0?-1000:sample(mode),hi=mode==0?1000:sample(mode);struct xnn_f32_minmax_params p={{lo,hi}};test_neon(1,N,K*4,E*8,table,W,L+1,0,32,off*4,zero,&p);test_rvv(1,N,K*4,E*8,table,W,R+1,0,32,off*4,zero,&p);for(size_t c=0;c<N;c++){float ref=oracle(c,K,E,table,zero,off,W,lo,hi);cells++;if(!same(L[c+1],ref)||!same(R[c+1],ref)){printf("mismatch N=%zu K=%zu entries=%zu pattern=%u mode=%u col=%zu neon=%08x rvv=%08x ref=%08x\n",N,K,E,pattern,mode,c,bits(L[c+1]),bits(R[c+1]),bits(ref));return 20;}}if(memcmp(A,AS,3*extent*4)||memcmp(W,WS,nw*4)||memcmp(table,copy,E*sizeof(*table)))return 21;if(bits(L[0])!=0x4f123456||bits(L[N+1])!=0x4f123456||bits(R[0])!=0xcf654321||bits(R[N+1])!=0xcf654321)return 22;cases++;free(A);free(AS);free(W);free(WS);free(L);free(R);free(table);free(copy);}printf("PASS cases=%zu observations=%zu\n",cases,cells);return 0;}
